"use client";

import { useRef } from "react";
import { motion, useInView, useReducedMotion } from "framer-motion";

export function RevealOnScroll({ children }: { children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { margin: "-10% 0px" });
  const shouldReduceMotion = useReducedMotion();
  const show = shouldReduceMotion || isInView;

  return (
    <motion.div
      ref={ref}
      initial={false}
      animate={
        show
          ? { opacity: 1, y: 0, filter: "blur(0px)" }
          : { opacity: 0, y: 24, filter: "blur(6px)" }
      }
      transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
      className="rounded-xl border border-slate-200 bg-white px-6 py-4 text-sm text-slate-600 dark:border-slate-700 dark:bg-neutral-950 dark:text-slate-300"
    >
      {children}
    </motion.div>
  );
}
